import {vinyl,memoryColors,memoryTheme,themeStyle,validColor} from './art.js';
import {drawConstellation,orbitPosition} from './constellation.js';
import{compose,render,Player,wav,moods,styles}from'./music.js';
const $=s=>document.querySelector(s),app=$('#app'),player=new Player(),KEY='recall-melody-v1',DRAFT=KEY+'-draft';
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const defaults=()=>({id:crypto.randomUUID(),title:'',memoryColor:'#39c9ef',story:'',story2:'',name1:'',name2:'',mode:'solo',mood:'warm',mood2:'happy',style:'piano',ending:'soft',instruments:{melody:false,harmony:true,bass:true,drums:false,piano:true,guitar:false,violin:false},variation:0,created:new Date().toISOString()});
let project=defaults(),step=0,view='home',buffers=null,score=null,busy=false,timer;
function read(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}}
let library=read(KEY,[]);if(!Array.isArray(library))library=[];library=library.flatMap(p=>{try{return[normalize(p)]}catch{return[]}});
function persist(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true}catch{toast('浏览器暂时无法保存，请导出作品备份');return false}}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(timer);timer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
function count(){$('#count').textContent=library.length}count();
function stop(){player.stop();document.querySelectorAll('[data-demo]').forEach(b=>b.textContent='▶')}
function nav(v){stop();view=v;document.querySelectorAll('.nav').forEach(b=>b.classList.toggle('active',b.dataset.nav===v));if(v==='home')home();if(v==='library')showLibrary();window.scrollTo({top:0,behavior:'smooth'})}
function home(){app.innerHTML=`<section class="hero"><div><div class="eyebrow">EVERY MEMORY HAS A MELODY</div><h1>有些瞬间，<br>值得被<em>听见。</em></h1><p>一场旅行，一次相遇，或一个舍不得忘记的普通日子。<br>聊聊你的故事，让回忆长成一段旋律。</p><div class="hero-actions"><button class="primary" id="start">♫ 开始我的创作</button><button class="secondary" id="duo">两个人的回忆</button></div><div class="hero-note">不需要懂乐理 · 免费创作 · 回忆保存在你的设备</div></div><div class="record-scene" aria-hidden="true"><div class="orbit"></div><span class="spark">✧</span><div class="record"><div class="label"><small>RECALL THE MELODY</small>那年夏天<small>SIDE A · MEMORY 001</small></div></div><div class="floating-note note-top">☀ 海风，和你<small>温暖 · 钢琴 · 轻鼓点</small></div><div class="floating-note note-bottom">♫ 把故事，慢慢谱成歌<small>属于你的回忆，属于你的声音。</small></div></div></section><section><div class="section-head"><div><h2>先听听，回忆的样子</h2><p>三段示例，给你的第一段旋律一点灵感。</p></div><span>A LITTLE INSPIRATION</span></div><div class="examples">${[['sea','≈','海边坐到天亮','温暖 · 舒缓钢琴',''],['summer','☀','放学后的那条路','快乐 · 轻快电子','sun'],['night','☾','写给晚一点的自己','平静 · 温柔氛围','night']].map(([id,icon,title,sub,cls])=>`<article class="example"><div class="cover ${cls}">${icon}</div><div><h3>${title}</h3><p>${sub}</p></div><button class="round" data-demo="${id}" aria-label="试听${title}">▶</button></article>`).join('')}</div></section><div class="bottom-note"><span><b>01</b> 说说你的故事</span><span><b>02</b> 选一份心情与声音</span><span><b>03</b> 收藏你的回忆旋律</span></div>`;$('#start').onclick=()=>start();$('#duo').onclick=()=>start('couple');document.querySelectorAll('[data-demo]').forEach(b=>b.onclick=()=>demo(b))}
function start(mode){const draft=read(DRAFT,null);try{project=draft?normalize(draft):defaults()}catch{project=defaults()}if(mode)project.mode=mode;step=0;view='editor';stop();editor();window.scrollTo(0,0)}
const option=(key,value,title,desc='',symbol='')=>`<button type="button" class="option ${project[key]===value?'selected':''}" data-key="${key}" data-value="${value}">${symbol?`<span class="symbol">${symbol}</span>`:''}${title}${desc?`<small>${desc}</small>`:''}</button>`;
function colorPicker(p=project,owner='project'){
 const t=memoryTheme(p);return `<div class="color-picker" data-owner="${owner}"><div class="color-heading"><span>这段回忆，是什么颜色？</span><span class="color-name">${t.name}</span></div><div class="color-swatches">${memoryColors.map(c=>`<button type="button" class="color-swatch ${t.hex===c.hex?'selected':''}" style="--swatch:${c.hex}" data-color="${c.hex}" data-owner="${owner}" aria-label="${c.name}：${c.word}" aria-pressed="${t.hex===c.hex}"><i></i><span>${c.name}</span></button>`).join('')}<label class="custom-swatch"><input type="color" value="${t.hex}" data-custom-color data-owner="${owner}" aria-label="自定义回忆颜色"><span>自选颜色</span></label></div><p class="color-help">选一个像它的颜色，让插画与唱片卡一起染上这份心情。</p></div>`
}
function wireColors(){
 const change=(value,owner)=>{const color=validColor(value);if(owner!=='project'){const index=Number(owner);if(!library[index])return;const next=library.map((p,i)=>i===index?{...p,memoryColor:color}:p);if(persist(KEY,next)){library=next;showLibrary();document.querySelector(`.color-picker[data-owner="${index}"]`)?.closest('details')?.setAttribute('open','')}return}
 project.memoryColor=color;if(view==='editor'){draft();editor()}else if(view==='result'){const card=$('.result-card');card.setAttribute('style',themeStyle(project));card.querySelector('.memory-vinyl').outerHTML=vinyl(project);card.querySelector('.color-picker').outerHTML=colorPicker();wireColors();const index=library.findIndex(p=>p.id===project.id);if(index>=0){const next=library.map((p,i)=>i===index?{...p,memoryColor:color}:p);if(persist(KEY,next))library=next}}
 };
 document.querySelectorAll('[data-color]').forEach(b=>b.onclick=()=>change(b.dataset.color,b.dataset.owner));document.querySelectorAll('[data-custom-color]').forEach(el=>el.onchange=()=>change(el.value,el.dataset.owner))
}
function formContent(){switch(step){case 0:return`<div class="step-kicker">开始 · 选择模式</div><h2>这是谁的回忆？</h2><p class="hint">可以独自收藏，也可以把设备交给身边的 TA，一起完成。</p><div class="options">${option('mode','solo','我的回忆','给自己，留住一个瞬间','♧')}${option('mode','couple','情侣回忆','用两个人的视角，写同一段故事','♡')}${option('mode','friends','朋友回忆','那些一起笑过、走过的日子','♬')}</div><p class="hint" style="margin-top:18px;margin-bottom:0">双人模式由两个人在同一设备上轮流填写。</p>`;
case 1:return`<div class="step-kicker">故事 · 留住瞬间</div><h2>你想把哪段时光留下？</h2><p class="hint">不必写得完整。一个地点、一件小事，都可以是旋律的起点。</p><label class="field" for="title">给这段回忆起个名字</label><input id="title" type="text" maxlength="40" data-field="title" value="${escape(project.title)}" placeholder="例如：那天我们错过了末班车"><label class="field" for="story">${project.mode==='solo'?'发生了什么？':'第一位：你记得的那个瞬间'}</label><textarea id="story" data-field="story" maxlength="1200" placeholder="那天，海边的风很大，我们一直坐到了天亮……">${escape(project.story)}</textarea>${project.mode!=='solo'?`<label class="field" for="story2">把设备交给 TA：你又记得什么？</label><textarea id="story2" data-field="story2" maxlength="1200" placeholder="从你的视角，补上这段共同回忆。">${escape(project.story2)}</textarea>`:''}`;
case 2:return`<div class="step-kicker">心情 · 回忆的颜色</div><h2>想起它时，是什么感觉？</h2><p class="hint">${project.mode==='solo'?'选一种最接近此刻的心情。':'先由第一位选择心情，再请 TA 选择。两份心情会影响各自的音乐段落。'}</p><div class="options">${Object.entries(moods).map(([v,t])=>option('mood',v,t)).join('')}</div>${project.mode!=='solo'?`<label class="field">TA 的心情</label><div class="options">${Object.entries(moods).map(([v,t])=>option('mood2',v,t)).join('')}</div>`:''}`+colorPicker();
case 3:return`<div class="step-kicker">声音 · 选择听感</div><h2>它应该是什么声音？</h2><p class="hint">不用了解音乐流派，选一个你喜欢的氛围就好。</p><div class="options">${option('style','piano','舒缓钢琴','轻柔的键盘音色，适合慢慢想起','♮')}${option('style','electronic','轻快电子','明亮的合成音色，和有弹性的节奏','⌁')}${option('style','ambient','温柔氛围','稀疏的旋律，让回忆缓缓展开','☾')}</div><label class="field">想让哪些声音加入？</label><div class="checks">${instrumentChecks()}</div><p class="hint" style="margin-top:12px;margin-bottom:0">钢琴勾勒主题，吉他铺开拨弦，小提琴拉长情绪。选好后，还可以在播放中随时开关。</p>`;
case 4:return`<div class="step-kicker">结尾 · 留一点余韵</div><h2>想让这段回忆怎样落下？</h2><p class="hint">选择音乐从开始到结尾的情绪走向。</p><div class="options">${option('ending','soft','轻轻落下','音乐逐渐舒缓，像合上一本手账','☾')}${option('ending','rise','带着期待','能量慢慢增加，像走向下一站','☀')}${option('ending','steady','留在此刻','保留平稳的心情，让时光停一会儿','≈')}</div>`;
case 5:return`<div class="step-kicker">确认 · 准备聆听</div><h2>让这段回忆，成为旋律。</h2><p class="hint">这是我们一起选好的创作方向。你可以返回修改，也可以现在听见它。</p><div class="summary">${escape(summary())}</div><p class="hint" style="margin-top:20px">故事文字会形成这首作品的旋律种子；你选择的心情、风格和结尾决定编曲。双人作品依次呈现两人的主题，再交替合奏。</p>`}}
function summary(){return`《${project.title||'未命名的回忆'}》将以${styles[project.style]}呈现${moods[project.mood]}的心情${project.mode!=='solo'?`，加入另一位${moods[project.mood2]}的主题`:''}。${project.ending==='rise'?'从轻柔开始，逐渐积蓄力量。':project.ending==='soft'?'最后让音乐轻轻落下。':'保持平稳的节奏，留在这一刻。'} ${project.instruments.drums?'加入鼓点，':''}${project.instruments.bass?'以贝斯铺垫低音。':''}`}
function instrumentChecks(){return Object.entries({piano:'钢琴',guitar:'吉他',violin:'小提琴',bass:'贝斯',drums:'鼓点',melody:'电子旋律',harmony:'氛围和声'}).map(([k,t])=>`<label class="check"><input type="checkbox" data-track="${k}" ${project.instruments[k]?'checked':''}>${t}</label>`).join('')}
function editor(){app.innerHTML=`<section class="workspace"><div class="workspace-title"><div class="eyebrow">A SOUNDTRACK OF YOUR OWN</div><h1>把故事，慢慢谱成旋律</h1><div class="steps">${Array.from({length:6},(_,i)=>`<span class="${i<=step?'on':''}"></span>`).join('')}</div></div><div class="editor"><div class="form-card">${formContent()}<div class="form-actions"><button class="secondary" id="back">${step?'上一步':'返回首页'}</button><button class="primary" id="next">${step===5?'♫ 生成我的旋律':'继续'}</button></div></div><aside class="preview"><div class="preview-title">YOUR MEMORY · 创作手账</div>${vinyl(project)}<h3 id="previewTitle">${escape(project.title||'等待命名的回忆')}</h3><div class="tags"><span class="tag">${project.mode==='solo'?'独自收藏':project.mode==='couple'?'情侣回忆':'朋友回忆'}</span><span class="tag">${moods[project.mood]}</span><span class="tag">${styles[project.style]}</span></div><p>封面从你的回忆场景中生长，<br>让每一段旋律，都有自己的样子。</p><p>草稿自动保存在当前浏览器。</p></aside></div></section>`;
 document.querySelectorAll('[data-key]').forEach(b=>b.onclick=()=>{project[b.dataset.key]=b.dataset.value;draft();editor()});document.querySelectorAll('[data-field]').forEach(el=>el.oninput=()=>{project[el.dataset.field]=el.value;draft();if(el.id==='title')$('#previewTitle').textContent=el.value||'等待命名的回忆'});wireTracks();wireColors();$('#back').onclick=()=>{if(step){step--;editor()}else nav('home')};$('#next').onclick=()=>{if(step===1&&(!project.title.trim()||!project.story.trim()||(project.mode!=='solo'&&!project.story2.trim()))){toast('请填写回忆名称和每位参与者的故事');return}if(step===3&&!Object.values(project.instruments).some(Boolean)){toast('至少保留一种声音吧');return}if(step===5)generate();else{step++;editor();window.scrollTo(0,0)}}}
function draft(){persist(DRAFT,project)}
function wireTracks(){document.querySelectorAll('[data-track]').forEach(el=>el.onchange=()=>{project.instruments[el.dataset.track]=el.checked;player.toggle(el.dataset.track,el.checked);if(view==='editor')draft()})}
async function generate(){if(busy)return;busy=true;stop();const b=$('#next');if(b){b.disabled=true;b.textContent='正在谱写旋律…'}try{score=compose(project);buffers=await render(score);view='result';result();window.scrollTo(0,0)}catch(e){toast('音频生成未完成，请使用支持 Web Audio 的现代浏览器重试');console.error(e)}finally{busy=false;if(b?.isConnected){b.disabled=false;b.textContent='♫ 生成我的旋律'}}}
function result(){app.innerHTML=`<section class="result"><div class="workspace-title"><div class="eyebrow">THIS MOMENT, IN MELODY</div><p>你的回忆，已经有了声音。</p></div><div class="result-card" style="${themeStyle(project)}">${vinyl(project)}<div class="tags" style="justify-content:center"><span class="tag">${styles[project.style]}</span><span class="tag">${moods[project.mood]}</span><span class="tag">${score.bpm} BPM</span></div><h1>${escape(project.title)}</h1><div class="story">${escape(project.story)}${project.mode!=='solo'?`<br><br>TA 记得：${escape(project.story2)}`:''}</div><details class="result-colors"><summary>给回忆换一种颜色 <span>◉</span></summary>${colorPicker()}</details><div class="player-console constellation-player"><div class="player-topline"><span>MELODY CONSTELLATION</span><span id="play-status">READY TO LISTEN</span></div><div class="orbit-stage"><canvas id="constellation" role="slider" tabindex="0" aria-label="星轨播放进度，方向键调整，Home 回到开头" aria-valuemin="0" aria-valuemax="${Math.floor(score.duration)}" aria-valuenow="0"></canvas><div class="orbit-core"><button class="play-main" id="play" aria-label="播放旋律">▶</button><span class="orbit-core-label">LISTEN TO<br>YOUR MEMORY</span></div><span class="orbit-caption">让回忆，沿着旋律运行</span></div><input class="seek accessible-seek" id="seek" type="range" min="0" max="${score.duration}" value="0" step=".1" aria-label="播放进度"><div class="player-timeline"><span id="time">0:00</span><span class="orbit-tip">轻触星轨 · 跳转时光</span><span>${clock(score.duration)}</span></div><div class="memory-chapters">${['起笔','回响','展开','余韵'].map((name,i)=>`<button class="chapter" data-chapter="${i}"><span class="chapter-dot">${['♪','♩','♫','♬'][i]}</span><span>${name}</span></button>`).join('')}</div></div><div class="checks">${instrumentChecks()}</div><div class="volume"><span>音量</span><input id="volume" aria-label="播放音量" type="range" min="0" max="1" step=".01" value="${player.volume}"></div><div class="tools"><button class="primary" id="save">收藏这段回忆</button><button class="secondary" id="audio">下载音频</button><button class="secondary" id="export">备份作品</button></div><div class="tools"><button class="text-btn" id="edit">修改创作方向</button><button class="text-btn" id="variation">再谱一个版本</button><button class="text-btn" id="new">创作下一段</button></div><p class="result-note">声音由此设备合成。作品备份可导入并还原旋律；音频下载为 WAV 格式。</p></div></section>`;wireTracks();wireColors();wireOrbit();$('#play').onclick=async()=>{try{if(player.playing){player.pause();$('#play').textContent='▶';$('#play').setAttribute('aria-label','播放旋律')}else{await player.play(buffers,project.instruments);$('#play').textContent='Ⅱ';$('#play').setAttribute('aria-label','暂停播放')}}catch{toast('无法播放，请检查浏览器音频权限')}};$('#seek').onchange=async e=>{try{await player.seek(Number(e.target.value),buffers,project.instruments)}catch{toast('跳转未完成，请重新播放')}};$('#volume').oninput=e=>player.setVolume(Number(e.target.value));$('#save').onclick=save;$('#export').onclick=()=>download(JSON.stringify({format:'recall-melody',version:1,project},null,2),'json','application/json');$('#audio').onclick=()=>download(wav(buffers,project.instruments),'wav');$('#edit').onclick=()=>{stop();view='editor';step=3;editor()};$('#variation').onclick=async()=>{project={...project,id:crypto.randomUUID(),variation:project.variation+1,created:new Date().toISOString()};$('#variation').disabled=true;await generate()};$('#new').onclick=()=>{stop();project=defaults();draft();start()}}
function wireOrbit(){
 const canvas=$('#constellation');let dragging=false,resume=false;
 const seek=async value=>{try{await player.seek(value,buffers,project.instruments)}catch{toast('跳转未完成，请重新播放')}};
 const move=e=>{if(dragging)seek(orbitPosition(e.clientX,e.clientY,canvas.getBoundingClientRect(),score.duration))};
 canvas.onpointerdown=e=>{resume=player.playing;if(resume)player.pause();dragging=true;canvas.setPointerCapture(e.pointerId);move(e)};canvas.onpointermove=move;canvas.onpointerup=canvas.onpointercancel=async()=>{dragging=false;if(resume){resume=false;try{await player.play(buffers,project.instruments)}catch{toast('无法继续播放，请重试')}}};
 canvas.onkeydown=e=>{let value;if(['ArrowRight','ArrowUp'].includes(e.key))value=player.time+1;if(['ArrowLeft','ArrowDown'].includes(e.key))value=player.time-1;if(e.key==='Home')value=0;if(e.key==='End')value=score.duration-.1;if(value!==undefined){e.preventDefault();seek(value)}};
 document.querySelectorAll('[data-chapter]').forEach(b=>b.onclick=()=>seek(Number(b.dataset.chapter)/4*score.duration));
}
function clock(t){return Math.floor(t/60)+':'+String(Math.floor(t%60)).padStart(2,'0')}
const reducedMotion=matchMedia('(prefers-reduced-motion: reduce)');let lastFrame=0;
function animatePlayer(now){
 if(now-lastFrame>32&&view==='result'&&score&&$('#time')){
  lastFrame=now;let t=player.time;if(player.playing&&t>=score.duration){stop();t=0;$('#play').textContent='▶';$('#play').setAttribute('aria-label','播放旋律')}
  const progress=Math.min(1,t/score.duration);$('#play').textContent=player.playing?'Ⅱ':'▶';$('#play').setAttribute('aria-label',player.playing?'暂停播放':'播放旋律');$('#time').textContent=clock(Math.min(t,score.duration));if(document.activeElement!==$('#seek'))$('#seek').value=t;
  $('.result-card').classList.toggle('is-playing',player.playing);$('#play-status').textContent=player.playing?'NOW PLAYING':t>0?'PAUSED':'READY TO LISTEN';
  const canvas=$('#constellation');canvas.setAttribute('aria-valuenow',Math.floor(t));canvas.setAttribute('aria-valuetext',`${clock(t)}，共 ${clock(score.duration)}`);
  drawConstellation(canvas,{levels:player.frequencies(),progress,time:now/1000,playing:player.playing,color:validColor(project.memoryColor),reduced:reducedMotion.matches});
  document.querySelectorAll('[data-chapter]').forEach((el,i)=>el.classList.toggle('active',i<=Math.floor(progress*4)))
 }
 requestAnimationFrame(animatePlayer)
}requestAnimationFrame(animatePlayer);

function save(){const existing=library.findIndex(p=>p.id===project.id),copy=JSON.parse(JSON.stringify(project));const next=[...library];if(existing>=0)next[existing]=copy;else next.unshift(copy);if(persist(KEY,next)){library=next;count();toast('已收藏到「我的回忆」；建议再导出一份备份')}}
function download(data,ext,type){const blob=data instanceof Blob?data:new Blob([data],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=(project.title||'回忆成调').replace(/[\\/:*?"<>|]/g,'_')+'.'+ext;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000)}
function showLibrary(){app.innerHTML=`<section class="workspace"><div class="library-head"><div><div class="eyebrow">YOUR LITTLE ARCHIVE</div><h1>把时光，收藏在这里。</h1><p class="hint">保存在当前浏览器，导出备份可以带到另一台设备。</p></div><button class="primary" id="create">新建回忆</button></div>${library.length?`<div class="saved-grid">${library.map((p,i)=>`<article class="saved" style="${themeStyle(p)}"><div class="saved-record">${vinyl(p)}<span class="record-caption">ORIGINAL MEMORY / ${String(i+1).padStart(2,'0')}</span></div><h3>${escape(p.title)}</h3><p>${moods[p.mood]||'温暖'} · ${styles[p.style]||'舒缓钢琴'}<br>${escape(new Date(p.created).toLocaleDateString('zh-CN'))}</p><details class="library-colors"><summary>回忆的颜色 <span>◉</span></summary>${colorPicker(p,String(i))}</details><div class="saved-actions"><button class="secondary" data-open="${i}">打开作品</button><button class="text-btn" data-delete="${i}">删除</button></div></article>`).join('')}</div>`:'<div class="empty"><p style="font-size:38px;color:#dba28f">♬</p><p>这里还很安静，等你的第一段回忆。</p></div>'}</section>`;wireColors();$('#create').onclick=()=>{project=defaults();draft();start()};document.querySelectorAll('[data-open]').forEach(b=>b.onclick=async()=>{if(busy)return;project=normalize(library[Number(b.dataset.open)]);b.disabled=true;b.textContent='正在还原…';await generate();if(b.isConnected){b.disabled=false;b.textContent='打开作品'}});document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{if(!confirm('删除这段本地回忆？已导出的备份不受影响。'))return;const next=library.filter((_,i)=>i!==Number(b.dataset.delete));if(persist(KEY,next)){library=next;count();showLibrary()}})}
function normalize(p){if(!p||typeof p!=='object'||!['solo','couple','friends'].includes(p.mode)||!Object.hasOwn(moods,p.mood)||!Object.hasOwn(styles,p.style)||typeof p.story!=='string')throw Error('invalid');const d=defaults();for(const k of ['title','story','story2'])d[k]=typeof p[k]==='string'?p[k].slice(0,k==='title'?40:1200):'';d.memoryColor=validColor(p.memoryColor);d.id=typeof p.id==='string'?p.id.slice(0,80):d.id;d.mode=p.mode;d.mood=p.mood;d.mood2=Object.hasOwn(moods,p.mood2)?p.mood2:'warm';d.style=p.style;d.ending=['soft','rise','steady'].includes(p.ending)?p.ending:'soft';d.variation=Number.isInteger(p.variation)?Math.max(0,Math.min(10000,p.variation)):0;d.created=typeof p.created==='string'&&!isNaN(Date.parse(p.created))?p.created:d.created;for(const k of Object.keys(d.instruments))d.instruments[k]=typeof p.instruments?.[k]==='boolean'?p.instruments[k]:['piano','guitar','violin'].includes(k)?false:k==='melody'?true:d.instruments[k];return d}
$('#import').onclick=()=>$('#file').click();$('#file').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>100000)throw Error();const data=JSON.parse(await f.text());if(data.format!=='recall-melody'||data.version!==1)throw Error();const imported=normalize(data.project);if(busy){toast('请等待当前旋律完成后再导入');return}project=imported;await generate();toast('作品已导入，可以试听并收藏')}catch{toast('无法导入，请选择本项目导出的有效 JSON 备份')}finally{e.target.value=''}};
async function demo(b){if(busy)return;if(player.playing){stop();return}busy=true;b.disabled=true;b.textContent='…';const p=defaults();p.story=b.dataset.demo;p.style=p.story==='summer'?'electronic':p.story==='night'?'ambient':'piano';p.mood=p.story==='summer'?'happy':p.story==='night'?'calm':'warm';p.instruments.drums=p.style==='electronic';p.instruments.melody=p.style==='electronic';p.instruments.piano=p.style!=='electronic';p.instruments.guitar=p.story==='sea';try{const s=compose(p),buf=await render(s);if(view==='home'){await player.play(buf,p.instruments);b.textContent='■';setTimeout(()=>{if(b.isConnected){stop();b.textContent='▶'}},10000)}}catch{toast('暂时无法试听，请检查浏览器音频支持')}finally{busy=false;b.disabled=false;if(b.textContent==='…')b.textContent='▶'}}
document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>nav(b.dataset.nav));$('.brand').onclick=e=>{e.preventDefault();nav('home')};home();
